final selectedCategoryIdProvider = StateProvider<String>((ref) => 'beer');
final searchQueryProvider = StateProvider<String>((ref) => '');

final filteredMenuProvider = Provider<List<MenuItem>>((ref) {
  final items = ref.watch(menuItemsProvider);
  final category = ref.watch(selectedCategoryIdProvider);
  final search = ref.watch(searchQueryProvider).toLowerCase();

  return items.where((item) {
    final matchesCategory = item.categoryId == category;
    final matchesSearch = item.name.toLowerCase().contains(search) || 
                          item.description.toLowerCase().contains(search);
    return matchesCategory && (search.isEmpty || matchesSearch);
  }).toList();
});
